pub mod open_poll {
    #[allow(unused_imports)]
    use super::defs;
    #[allow(unused_imports)]
    use serde::{Deserialize, Serialize};

    pub type Output = defs::PollView;

    #[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
    #[cfg_attr(feature = "strict", serde(deny_unknown_fields))]
    pub struct Input {
        /// The LAST option is the abstention: chosen alone or not at all, and never the winner.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub blank: Option<bool>,
        /// The counts, and a secret poll's board, are for the owners of the context. The turnout is still everyone's.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub hide_tally: Option<bool>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub max: Option<i64>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub min: Option<i64>,
        /// A ballot records an option's INDEX, so the order is part of the poll. `for`, `against` and `blank` are markers the client translates; anything else is shown as written.
        pub options: Vec<String>,
        /// The motion, amendment, question or position put to the vote.
        pub parent_id: String,
        /// The wording voted on, fixed for the life of the poll. The title if absent.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub question: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        pub secret: Option<bool>,
        pub title: String,
    }

}

