pub mod resolve_node {
    #[allow(unused_imports)]
    use super::defs;
    #[allow(unused_imports)]
    use serde::{Deserialize, Serialize};

    /// A contextView or a documentView, told apart by an added `node` field: `context` or `document`.
    #[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
    #[serde(tag = "node", rename_all = "snake_case")]
    pub enum Output {
        Context(defs::ContextView),
        Document(defs::DocumentView),
    }

    #[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
    #[cfg_attr(feature = "strict", serde(deny_unknown_fields))]
    pub struct Params {
        /// The slugs from the root, slash-joined, as a URL carries them; empty segments are ignored.
        pub path: String,
    }

}

impl resolve_node::Params {
    pub(crate) fn pairs(&self) -> Vec<(&'static str, String)> {
        let pairs = vec![
            ("path", self.path.to_string()),
        ];
        pairs
    }
}

